   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (5. ඔකාරන්තපුල්ලිඞ්ගනාමිකපදමාලා) ගන්නා ලදී.",
   "පදමාලාව ‘‘පුරිසො, පුරිසා, පුරිස’’න්ති නිරුත්තිපිටක නයය ඇසුරෙන් භූත ශබ්දයාගේ නාමිකපදමාලාව දක්වයි.",
