  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (5. ඔකාරන්තපුල්ලිඞ්ගනාමිකපදමාලා) ගන්නා ලදී.",
   "‘‘කිං කයිරා උදපානෙන, ආපා චෙ සබ්බදා සියු’’න්ති උදාන පාළිය අනුව ආප ශබ්දයේ බහුවචනයද ගන්නා බව පදමාලාව කියයි.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, පුරිස ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
