  "linga": "පුල්ලිඞ්ග",
  "meaning": "වාතය; ශරීරය (‘කකුධරුක්ඛො, කරජකායො’ ආදියෙහි)",
  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (10. ලිඞ්ගත්තයමිස්සකනාමිකපදමාලා) ගන්නා ලදී.",
   "‘කකුධරුක්ඛො’ යන තැන කො = වාතය; ‘කරජකායො’ යන තැන කො = ශරීරය බව පදමාලාව දක්වයි.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, පුරිස ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
