  "meaning": "මහරජු; සතරවරම් දෙවිරජු",
  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (6. ආකාරන්තපුල්ලිඞ්ගනාමිකපදමාලා) ගන්නා ලදී.",
   "‘මහාරාජො’ ලෙස ඔකාරන්ත නයින්ද, මෙහි දැක්වෙන පරිදි ආකාරන්ත (රාජ) නයින්ද පදමාලාව වරනඟයි.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, රාජ ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
