   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (6. ආකාරන්තපුල්ලිඞ්ගනාමිකපදමාලා) ගන්නා ලදී.",
   "‘භො දළ්හධම්මානො, භො දළ්හධම්මා’ ලෙස බහුවචනයද දත යුතු බවත්, පච්චක්ඛධම්ම ශබ්දයද මෙසේ වරනැඟිය යුතු බවත් පදමාලාව කියයි.",
