  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (7. නිග්ගහීතන්තපුල්ලිඞ්ගනාමිකපදමාලා) ගන්නා ලදී.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, ගච්ඡන්ත, පුරිස ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
