  "sub_khanda_name": "පුල්ලිඞ්ග පද සාධනය",
  "word": "සන්ත",
  "stem": "සන්ත",
  "ending": "අකාරාන්ත (න්ත ප්‍රත්‍යය)",
  "linga": "පුල්ලිඞ්ග",
  "meaning": "සත්පුරුෂයා; විද්‍යමාන වූයේ",
  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (7. නිග්ගහීතන්තපුල්ලිඞ්ගනාමිකපදමාලා) ගන්නා ලදී.",
   "සත්පුරුෂ අර්ථයෙහි එක් පදමාලාවක්ද, ‘විද්‍යමාන’ අර්ථයෙහි (සන්තො, සන්තා ...) තවත් පදමාලාවක්ද පදමාලාව දක්වයි; මෙහි දෙකම එක්කොට ඇත.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, ගච්ඡන්ත, පුරිස ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
