  "meaning": "පක්ෂියා (‘වීනං ඉන්දො වින්දො’)",
  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (10. ලිඞ්ගත්තයමිස්සකනාමිකපදමාලා) ගන්නා ලදී.",
   "පදමාලාවෙහි පඨමා එකවචනය ‘විං’ ලෙස මුද්‍රණය වී ඇත; අනෙක් ඉකාරන්ත නයට අනුව මෙහි ‘වි’ ලෙස ගෙන ඇත.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, අග්ගි ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
