   "‘වදඤ්ඤූ’ යන පච්චත්ත බහුවචනය දැකීමෙන් සයම්භූ, සබ්බඤ්ඤූ ආදීන්ගේද පඨමා-දුතියා බහුවචන ඌකාරන්ත රූප ගන්නා බව පදමාලාව කියයි.",
